    if (theUnsafe != null && unsafeClass != null && overrideField != null) {
      // After the null-check, capture in a local variable so NullAway treats it as non-null
      Class<?> unsafeClassLocal = unsafeClass;
      try {
        Method method = unsafeClassLocal.getMethod("objectFieldOffset", Field.class);
        long overrideOffset = (Long) method.invoke(theUnsafe, overrideField);
        Method putBooleanMethod =
            unsafeClassLocal.getMethod("putBoolean", Object.class, long.class, boolean.class);
        putBooleanMethod.invoke(theUnsafe, ao, overrideOffset, true);
        return true;
      } catch (Exception ignored) {
        // do nothing
      }
    }
    return false;
  }

  private static @Nullable Object getUnsafeInstance() {
    try {
      unsafeClass = Class.forName("sun.misc.Unsafe");
      Field unsafeField = unsafeClass.getDeclaredField("theUnsafe");
      unsafeField.setAccessible(true);
      return unsafeField.get(null);
    } catch (Exception e) {
      return null;
    }
  }

  private static @Nullable Field getOverrideField() {
    try {
      return AccessibleObject.class.getDeclaredField("override");
    } catch (NoSuchFieldException e) {
      return null;
    }
  }
}
